            reject: [{ re: 'wrong|false|useless', hint: 'A limit makes the point smaller, not wrong. Keep your verdict.' },
              { re: '^because', hint: 'The limit leads to this, so the linker shows a result.' },
              { re: '\\bhave its\\b', hint: 'One point: check the verb.' }],
